/* ═══ filter — Panda's own fields and rules (HV_FELTER / HV_OPS / hvOpfylder), shown in English ═══ */
const FN = { status: 'Status', branch: 'Branch', owner: 'Owner', stage: 'Stage', destination: 'Destination', departure_date: 'Departure', budget: 'Budget', liggetid: 'Days on stage', boern: 'Travelling with children', spor: 'Came in via' };
