/* ═══ saving — the same columns and values as Panda's hvSave ═══ */
async function save(patch, quiet){
  const id = S.open, r0 = raw(id); if(!r0) return false;
  if(typeof hvMinAendring === 'function') hvMinAendring(id);
  const { error } = await db.from('leads').update(patch).eq('id', id);
  if(error){ savedPing(error.message); if(S.open === id) drawD(); return false; }
  Object.assign(r0, patch); window._hvAendret = true; rebuild();
  if(S.open === id && !quiet) drawD();
  savedPing(); return true;
}
function saveField(f, v, el){
  const r = raw(S.open); if(!r) return;
  const num = x => { const n = parseInt(String(x).replace(/\D/g, ''), 10); return isNaN(n) ? null : n; };
  switch(f){
    case 'contact_name': { const t = String(v || '').trim(); if(t === (r.contact_name || '')) return; return save({ contact_name: t || null }); }
    case 'branch': return save({ branch: v || null });
    case 'owner': return save({ owner: v || null });
    case 'departure_date': { const p = { departure_date: v || null }; if(v && !r.return_date && typeof hvUgeEfter === 'function'){ const f2 = hvUgeEfter(v); if(f2) p.return_date = f2; } return save(p); }
    case 'return_date': return save({ return_date: v || null });
    case 'nights': case 'villas': case 'adults': return save({ [f]: num(v) });
    case 'kids': { const n = num(v); return save({ kids: n == null ? null : Math.min(12, n) }); }
    case 'est_value': { const n = hvTal(v); if(el) el.value = n == null ? '' : fval(n); if(n === (typeof budgetTal === 'function' ? budgetTal(r.est_value) : r.est_value)) return; return save({ est_value: n }); }
    case 'currency': { if(!v) return; const br = String(r.branch || '').trim().toUpperCase(), vent = (typeof HV_BRANCHE_VALUTA !== 'undefined' ? HV_BRANCHE_VALUTA : {})[br];
      if(vent && v !== vent) return curDlg(r, v, vent); return save({ currency: v }); }
    case 'contact_email': { const t = String(v || '').trim(); if(t === (r.contact_email || '')) return; return save({ contact_email: t || null }); }
    case 'contact_phone': { const t = String(v || '').trim(); if(t.replace(/\s/g, '') === String(r.contact_phone || '').replace(/\s/g, '')) return; return save({ contact_phone: t || null }); }
  }
}
function curDlg(r, v, vent){
  const w = dlg('<div class="h"><h3>Is the currency right?</h3><p>The enquiry belongs to ' + esc(BRANCH[r.branch] || r.branch) + ', which is normally in ' + vent + '. You are about to set the budget to ' + v + '.</p></div><div class="f"><span class="sp"></span><button class="b" id="cuNo">No — keep ' + vent + '</button><button class="b pri" id="cuOk">Yes, ' + v + '</button></div>');
  w.querySelector('#cuNo').addEventListener('click', () => { closeDlg(); save({ currency: vent }); });
  w.querySelector('#cuOk').addEventListener('click', () => { closeDlg(); save({ currency: v }); });
  w.addEventListener('click', e => { if(e.target === w) drawD(); });
}
const saveDests = list => save({ destination: list.length ? list.join(', ') : null });
const saveAps = list => save({ departure_airport: list.length ? list.join(', ') : null });
function saveAges(){ const v = [...$('dv').querySelectorAll('[data-age]')].map(i => i.value.replace(/\D/g, '')).filter(x => x !== ''); return save({ child_ages: v.length ? v.join(', ') : null }, true); }

/* the assessment — one row per person in lead_vurderinger, the same upsert as Panda's hv8SaetVur */
async function writeVur(id, k){
  const mig = ME_I(); if(!mig) return 'You are not logged in with initials — the assessment can’t be saved.';
  const har = (DT.id === id ? DT.vur : []).find(v => v.hvem === mig), now = new Date().toISOString();
  const rk = Object.assign({ lead_id: id, hvem: mig, vurdering: k }, har ? { aendret_at: now } : { sat_at: now });
  if(typeof hvMinAendring === 'function') hvMinAendring(id);
  const r = await db.from('lead_vurderinger').upsert(rk, { onConflict: 'lead_id,hvem' }).select();
  if(r.error || !(r.data || []).length) return 'The assessment was NOT saved: ' + (r.error ? r.error.message : 'the database wrote no row');
  if(DT.id === id) DT.vur = DT.vur.filter(v => v.hvem !== mig).concat(r.data[0]);
  if(window._hvId === id) window._hvVur = DT.vur;
  const l = raw(id); if(l){ l.vurdering = k; l.vurdering_by = mig; l.vurdering_at = now; }
  return null;
}
async function setVur(k){
  const id = S.open; const err = await writeVur(id, k);
  if(err){ const f = $('vFejl'); if(f) f.textContent = err; return toast(err, 1); }
  if(dvPend && dvPend.id === id){ const st = dvPend.stage; dvPend = null; toast('Your assessment is saved — the enquiry is being moved'); return moveTo(id, st); }
  drawD(); toast('Your assessment is saved');
}
function nudgeVur(what){ toast(vurMangler(what));
  const v = $('vbox'); if(v){ v.scrollIntoView({ behavior: 'smooth', block: 'center' }); const r = $('vreq'); if(r){ r.classList.remove('wave'); void r.offsetWidth; r.classList.add('wave'); } } }
function railMove(k){ const r = raw(S.open); if(!r) return; if(homeOf(r.stage) === k) return;
  if(r.status !== 'open') return toast('Reopen the enquiry before moving it');
  if(!mineV()){ dvPend = { id: r.id, stage: k }; drawD(); return nudgeVur('the enquiry is moved'); }
  moveTo(r.id, k); }

