/* ═══ choosing a destination — Panda's own list (HV_TOP and HV_DEST_GROUPS), shown in English ═══ */
function destDlg(){
  const r = raw(S.open); if(!r) return; const have = destList(r.destination);
  const pick = n => { const cur = destList(raw(S.open).destination); if(!cur.includes(n)) saveDests(cur.concat([n])); closeDlg(); };
  const btn = (n, c) => '<button type="button" data-dp="' + esc(n) + '"' + (have.includes(n) ? ' disabled' : '') + '>' + esc(destEn(n)) + (c ? '<small>' + c + '</small>' : '') + '</button>';
  const w = dlg('<div class="h"><h3>Choose destination</h3><p>Where does the customer want to go?</p></div><div class="c"><input class="inp" id="dpQ" placeholder="Search destination…" autocomplete="off"><div class="grid" id="dpG"></div></div><div class="f"><span class="sp"></span><button class="b" data-x="1">Close</button></div>');
  w.querySelector('.dlg').classList.add('dpk');
  const TOP = typeof HV_TOP !== 'undefined' ? HV_TOP : [], GR = typeof HV_DEST_GROUPS !== 'undefined' ? HV_DEST_GROUPS : [];
  const all = [...new Set(TOP.map(t => t[0]).concat(...GR.map(g => g[1])))];
  const draw = () => { const q0 = w.querySelector('#dpQ').value.trim(), q = q0.toLowerCase(), g = w.querySelector('#dpG');
    if(!q){ g.innerHTML = '<div class="gh">Your best sellers</div>' + TOP.map(t => btn(t[0], t[1])).join('') + GR.map(([h, ls]) => '<div class="gh">' + esc(GRUPPE_EN[h] || h) + '</div>' + ls.map(n => btn(n)).join('')).join(''); return; }
    const hit = all.filter(n => n.toLowerCase().includes(q) || destEn(n).toLowerCase().includes(q));
    g.innerHTML = (hit.length ? hit.map(n => btn(n)).join('') : '<div style="font-size:13px;color:var(--mut);width:100%">No match.</div>') + (hit.some(n => n.toLowerCase() === q || destEn(n).toLowerCase() === q) ? '' : '<button type="button" data-dp="' + esc(q0) + '">＋ Add «' + esc(q0) + '» as a new destination</button>'); };
  draw(); w.querySelector('#dpQ').addEventListener('input', draw);
  w.querySelector('#dpQ').addEventListener('keydown', e => { if(e.key === 'Enter'){ const b = w.querySelector('#dpG [data-dp]:not([disabled])'); if(b){ e.preventDefault(); pick(b.dataset.dp); } } });
  w.addEventListener('click', e => { const b = e.target.closest('[data-dp]'); if(b && !b.disabled) pick(b.dataset.dp); }); }

/* ═══ copying ═══ */
function copy(b){ const u = b.dataset.copy, w = b.dataset.what || 'Link';
  const ok = () => { toast(w + ' copied'); b.classList.add('done'); setTimeout(() => b.classList.remove('done'), 1400); };
  const fail = () => { const i = b.parentElement.querySelector('input'); if(i){ i.focus(); i.select(); toast('Press Cmd+C to copy'); } else toast('Select the text to copy it'); };
  try { navigator.clipboard.writeText(u).then(ok, fail); } catch(_){ fail(); } }

/* ═══ wiring — every button on the page does something ═══ */
let dragId = null, fitT = null, KEYS = false;
function wire(){
  const side = $('side');
  { let tIn, tOut;
    side.addEventListener('mouseenter', () => { clearTimeout(tOut); if(!side.classList.contains('mini') || matchMedia('(hover:none)').matches) return; tIn = setTimeout(() => side.classList.add('peek'), 110); });
    side.addEventListener('mouseleave', () => { clearTimeout(tIn); tOut = setTimeout(() => side.classList.remove('peek'), 220); });
    side.addEventListener('focusin', () => { if(side.classList.contains('mini')) side.classList.add('peek'); });
    side.addEventListener('focusout', e => { if(!side.contains(e.relatedTarget)) side.classList.remove('peek'); }); }
  $('stog').addEventListener('click', () => sideSet(!side.classList.contains('mini')));
  $('mMenu').addEventListener('click', () => { const o = !side.classList.contains('mopen'); if(o){ side.dataset.mini = side.classList.contains('mini') ? '1' : ''; side.classList.remove('mini'); } else if(side.dataset.mini) side.classList.add('mini'); side.classList.toggle('mopen', o); $('mMenu').setAttribute('aria-label', o ? 'Close the menu' : 'Menu'); });
  [$('nav'), $('nav2')].forEach(n => n.addEventListener('click', e => { const a = e.target.closest('a[data-v]'); if(!a) return; e.preventDefault(); if(side.classList.contains('mopen')){ side.classList.remove('mopen'); if(side.dataset.mini) side.classList.add('mini'); } goNav(a.dataset.v); }));
  $('meact').addEventListener('click', e => { const a = e.target.closest('a[data-a]'); if(!a) return; e.preventDefault();
    if(a.dataset.a === 'pw'){ if(typeof changePassword === 'function') changePassword(); } else if(a.dataset.a === 'out'){ luk(); db.auth.signOut(); } });
  R.querySelectorAll('.brand').forEach(b => b.addEventListener('click', e => { e.preventDefault(); goNav('dash'); }));
  /* filter bar */
  $('fbar').addEventListener('click', e => {
    const m = e.target.closest('[data-menu]'); if(m){ S.menu = S.menu === m.dataset.menu ? null : m.dataset.menu; renderBar(); return; }
    const ed = e.target.closest('[data-edit]'); if(ed){ e.stopPropagation(); S.menu = null; renderBar(); editViewDlg(ed.dataset.edit); return; }
    const vw = e.target.closest('[data-view]'); if(vw){ const v = (window._hvViews || []).find(x => x.id === vw.dataset.view); if(v){ const f = hvFraGammel(v.filter); S.menu = null; setFilter({ b: f.b.map(x => Object.assign({}, x)) }); } return; }
    const d = e.target.closest('[data-del]'); if(d){ const f = filt(); setFilter({ b: f.b.filter((_, i) => i !== +d.dataset.del).map(x => Object.assign({}, x)) }); return; }
    const a = e.target.closest('[data-act]'); if(!a) return;
    if(a.dataset.act === 'allopen' || a.dataset.act === 'clear'){ S.menu = null; setFilter(hvStdFilter()); }
    if(a.dataset.act === 'done'){ S.menu = null; renderBar(); }
    if(a.dataset.act === 'saveview'){ S.menu = null; renderBar(); saveViewDlg(); }
    if(a.dataset.act === 'addcond'){ const f = filt(), used = new Set(f.b.map(x => x.f)), k = Object.keys(HV_FELTER).find(x => !used.has(x)) || 'branch', F = HV_FELTER[k];
      setFilter({ b: f.b.map(x => Object.assign({}, x)).concat([{ f: k, op: HV_OPS[F.type][0][0], v: F.type === 'valg' ? (fieldOpts(k)[0] || [''])[0] : F.type === 'janej' ? 'ja' : '' }]) }); }
  });
  $('fbar').addEventListener('change', e => { const t = e.target; if(t.dataset.ci != null) setCond(+t.dataset.ci, t.dataset.k, t.value); });
  $('fbar').addEventListener('keydown', e => { if(e.target.dataset.ci != null && e.key === 'Enter') e.target.blur(); });
  R.addEventListener('click', e => { if(S.menu && !e.target.closest('.grp')){ S.menu = null; renderBar(); } if(!e.target.closest('.srch')){ const s = $('sres'); if(s) s.hidden = true; } });
  R.addEventListener('click', e => { const a = e.target.closest && e.target.closest('a[href="#"]'); if(a) e.preventDefault(); });
  /* stage strip and board */
  $('strip').addEventListener('click', e => { const b = e.target.closest('[data-stage]'); if(!b) return; const k = b.dataset.stage; S.stage = k; render();
    const nb = $('strip').querySelector('[data-stage="' + k + '"]'); if(nb && nb.scrollIntoView) nb.scrollIntoView({ inline: 'center', block: 'nearest' });
    const band = R.querySelector('#ovw .band'), top = band.getBoundingClientRect().top - SCR.getBoundingClientRect().top + SCR.scrollTop - 90;
    if(SCR.scrollTop < top - 40 || PHONE()) SCR.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });
    if(!PHONE()){ const col = $('tav').querySelector('.sj[data-stage="' + k + '"]'), wrap = R.querySelector('.tav-wrap'); if(col && wrap){ wrap.scrollTo({ left: Math.max(0, col.offsetLeft - 20), behavior: 'smooth' }); col.classList.remove('flash'); void col.offsetWidth; col.classList.add('flash'); } } });
  const tav = $('tav');
  tav.addEventListener('dragstart', e => { const k = e.target.closest('.k'); if(!k) return; dragId = k.dataset.id; k.classList.add('drag'); e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', dragId); } catch(_){} });
  tav.addEventListener('dragend', e => { const k = e.target.closest('.k'); if(k) k.classList.remove('drag'); tav.querySelectorAll('.sj.over').forEach(s => s.classList.remove('over')); dragId = null; });
  tav.addEventListener('dragover', e => { const s = e.target.closest('.sj'); if(!s || !dragId) return; e.preventDefault(); tav.querySelectorAll('.sj.over').forEach(x => x !== s && x.classList.remove('over')); s.classList.add('over'); });
  tav.addEventListener('drop', e => { const s = e.target.closest('.sj'); if(!s || !dragId) return; e.preventDefault(); s.classList.remove('over'); const id = dragId; dragId = null; const r = raw(id); if(r && homeOf(r.stage) !== s.dataset.stage) moveTo(id, s.dataset.stage); });
  tav.addEventListener('click', e => { const k = e.target.closest('.k'); if(k) openD(k.dataset.id); });
  tav.addEventListener('keydown', e => { const k = e.target.closest('.k'); if(k && (e.key === 'Enter' || e.key === ' ')){ e.preventDefault(); openD(k.dataset.id); } });
  $('bNy').addEventListener('click', () => newDlg());
  /* search */
  $('q').addEventListener('input', search);
  $('q').addEventListener('keydown', e => { if(e.key === 'Escape'){ e.stopPropagation(); $('q').value = ''; search(); } if(e.key === 'Enter'){ const b = $('sres').querySelector('[data-id]'); if(b){ e.preventDefault(); b.click(); } } });
  $('sres').addEventListener('click', e => { const b = e.target.closest('[data-id]'); if(!b) return; const l = lv(b.dataset.id); $('sres').hidden = true; if(!l) return;
    if(!shown().some(x => x.id === l.id)) window._hvFilter = { b: [{ f: 'status', op: 'er', v: l.stt }] };
    S.stage = l.col; render(); openD(l.id); });
  $('qx').addEventListener('click', () => { $('q').value = ''; search(); $('q').focus(); });
  /* the enquiry page */
  const dv = $('dv');
  dv.addEventListener('change', e => { const t = e.target; if(!S.open) return;
    if(t.dataset.a === 'addap'){ if(t.value){ const a = splitC(raw(S.open).departure_airport); if(!a.includes(t.value)) a.push(t.value); saveAps(a); } return; }
    if(t.dataset.age != null) return saveAges();
    if(t.dataset.f) return saveField(t.dataset.f, t.value, t); });
  dv.addEventListener('keydown', e => { const t = e.target;
    if(t.classList.contains('dname') && e.key === 'Enter'){ e.preventDefault(); t.blur(); }
    if(t.id === 'dvOff' && e.key === 'Enter'){ e.preventDefault(); addOffer(); }
    if(t.id === 'dvNote' && e.key === 'Enter' && (e.metaKey || e.ctrlKey)){ e.preventDefault(); addNote(); } });
  dv.addEventListener('focusout', e => { const t = e.target, r = raw(S.open); if(!r) return;
    if(t.dataset && t.dataset.w){ const v = t.innerText.replace(/\n$/, ''); if(v !== wishOf(r)) save({ travel_wishes: v }, true); }
    setTimeout(flush, 0); });
  dv.addEventListener('toggle', e => { if(e.target.classList && e.target.classList.contains('trk2')) S.trkOpen = e.target.open; }, true);
  dv.addEventListener('click', e => { if(!S.open) return; const q = s => e.target.closest(s), r = raw(S.open); if(!r) return; let b;
    if((b = q('[data-step]'))) return step(+b.dataset.step);
    if((b = q('.srail [data-stage]'))) return railMove(b.dataset.stage);
    if((b = q('[data-inc]'))){ const f = b.dataset.inc, cur = tnum(r[f]) || 0, n = Math.max(0, cur + (+b.dataset.d)); return saveField(f, String(n)); }
    if((b = q('[data-tgo]'))){ S.tgOpen = b.dataset.tgo || null; return drawD(); }
    if((b = q('[data-tag]'))){ const k = b.dataset.tag, a = arr(r[k]); if(!a.includes(b.dataset.v)) a.push(b.dataset.v); return save({ [k]: a }); }
    if((b = q('[data-untag]'))){ const k = b.dataset.untag, a = arr(r[k]).filter(x => x !== b.dataset.v); return save({ [k]: a.length ? a : null }); }
    if((b = q('[data-deldest]'))){ const a = destList(r.destination); a.splice(+b.dataset.deldest, 1); return saveDests(a); }
    if((b = q('[data-delap]'))){ const a = splitC(r.departure_airport); a.splice(+b.dataset.delap, 1); return saveAps(a); }
    if((b = q('[data-vur]'))) return setVur(b.dataset.vur);
    if((b = q('[data-copy]'))) return copy(b);
    if((b = q('[data-merge]'))) return mergeFlow(b.dataset.merge);
    if((b = q('[data-offdel]'))){ S.offDel = b.dataset.offdel; return drawD(); }
    if((b = q('[data-offyes]'))) return delOffer(b.dataset.offyes);
    if((b = q('[data-ndel]'))){ S.noteDel = b.dataset.ndel; return drawD(); }
    if((b = q('[data-nyes]'))) return delNote(b.dataset.nyes);
    if(!(b = q('[data-a]')) || b.tagName === 'SELECT') return;
    switch(b.dataset.a){
      case 'back': e.preventDefault(); return closeD();
      case 'sold': return soldFlow();
      case 'lost': return lostDlg();
      case 'reopen': return reopen();
      case 'trip': { const id = r.converted_trip_id; luk(); if(typeof viewTrip === 'function') viewTrip(id); return; }
      case 'del': return delDlg();
      case 'adddest': return destDlg();
      case 'addoff': return addOffer();
      case 'addnote': return addNote();
      case 'offno': S.offDel = null; return drawD();
      case 'nno': S.noteDel = null; return drawD();
      case 'histall': S.histAll = true; return drawD();
      case 'retry': return openD(S.open);
    } });
  addEventListener('resize', () => { clearTimeout(fitT); fitT = setTimeout(() => { if(R) fitCards(); }, 120); });
  if(!KEYS){ KEYS = true; document.addEventListener('keydown', onKey, true); }
}
function onKey(e){
  if(!R || legacyOpen()) return;
  const a = R.activeElement, typing = a && (/^(INPUT|SELECT|TEXTAREA)$/.test(a.tagName) || a.isContentEditable);
  if(e.key === 'Escape'){
    if(R.querySelector('.dov')){ e.stopPropagation(); return closeDlg(); }
    if(S.tgOpen){ S.tgOpen = null; e.stopPropagation(); return drawD(); }
    if(typing){ a.blur(); return; }
    if(S.open){ e.stopPropagation(); return closeD(); }
    if(S.menu){ S.menu = null; renderBar(); }
    return; }
  if(S.open && !R.querySelector('.dov') && !typing && !e.metaKey && !e.ctrlKey && !e.altKey){ if(e.key === 'ArrowRight'){ e.preventDefault(); step(1); } if(e.key === 'ArrowLeft'){ e.preventDefault(); step(-1); } }
}

return { version: VERSION, board, open, luk, _state: () => ({ S, DT, open: !!VAERT }), _root: () => R };
